-- Unificación de Pedidos, parte 3: los 162 productos reales del proyecto
-- de Andrés pasan a catalogo.productos.
--
-- proveedor_id queda en null a propósito. Los 4 proveedores de Andrés
-- (Diphasac 90 productos, Biosana 50, Prades 22) están cargados solo con
-- nombre, sin RUC, y compras.proveedores exige RUC — que es un identificador
-- fiscal y no se inventa. Cuando existan los RUCs se cargan los proveedores
-- y se reapunta por prefijo de codigo, que es estable (BSA*, PLGS*, ...).
--
-- 21 productos traían un NÚMERO en unidad_medida en vez de una unidad
-- ('70.3390', '62.7119', ...). Todos son PLGS* (Prades) y todos multiplicados
-- por 1.18 dan un valor redondo: son precios sin IGV que cayeron en la
-- columna equivocada al importar esa lista de precios. Se normalizan a 'UND'
-- y el valor original queda registrado en nota_estado, para que Compras
-- pueda corregirlo sin perder el dato.
--
-- Re-ejecutable: on conflict (codigo) actualiza.
insert into catalogo.productos
  (codigo, codigo_proveedor, codigo_bonificacion, descripcion, presentacion,
   marca, principio_activo, unidad_medida, estado, nota_estado,
   controla_lote, controla_vencimiento, peso_unitario)
